package e2e

import (
	"net/http"
	"testing"

	"github.com/stretchr/testify/require"
)

// TestProjectTimelineShowsEvents verifies that GET /projects/{prjId}/timeline
// returns events generated by task operations within the project.
func TestProjectTimelineShowsEvents(t *testing.T) {
	bootstrap(t)
	t.Parallel()
	tt := newTenant(t)

	// Create a task (generates task.created event).
	var task struct {
		ID string `json:"id"`
	}
	doJSON(t, http.MethodPost, testServerURL+"/tasks", tt.AccessToken,
		map[string]any{"projectId": tt.ProjectPublicID, "title": "Timeline event source"}, &task)

	// Transition the task (generates task.transition event).
	doJSON(t, http.MethodPost,
		testServerURL+"/tasks/"+task.ID+"/transitions",
		tt.AccessToken, map[string]any{"transition": "start"}, nil)

	// Fetch project timeline.
	var timeline struct {
		Total  int64 `json:"total"`
		Events []struct {
			ID   string `json:"id"`
			Type string `json:"type"`
		} `json:"events"`
	}
	doJSON(t, http.MethodGet,
		testServerURL+"/projects/"+tt.ProjectPublicID+"/timeline",
		tt.AccessToken, nil, &timeline)

	require.Greater(t, timeline.Total, int64(0),
		"project timeline must contain events after task operations")

	// At least one event should be present.
	require.NotEmpty(t, timeline.Events)
	for _, ev := range timeline.Events {
		require.NotEmpty(t, ev.ID)
		require.NotEmpty(t, ev.Type)
	}
}

// TestProjectTimelinePagination verifies that the project timeline
// supports limit/offset pagination.
func TestProjectTimelinePagination(t *testing.T) {
	bootstrap(t)
	t.Parallel()
	tt := newTenant(t)

	// Create several tasks to generate events.
	for i := 0; i < 3; i++ {
		doJSON(t, http.MethodPost, testServerURL+"/tasks", tt.AccessToken,
			map[string]any{
				"projectId": tt.ProjectPublicID,
				"title":     "Timeline paginate " + randomHex(4),
			}, nil)
	}

	// Fetch page 1 with limit=1.
	var page1 struct {
		Total  int64 `json:"total"`
		Events []struct {
			ID string `json:"id"`
		} `json:"events"`
	}
	doJSON(t, http.MethodGet,
		testServerURL+"/projects/"+tt.ProjectPublicID+"/timeline?limit=1&offset=0",
		tt.AccessToken, nil, &page1)
	require.GreaterOrEqual(t, page1.Total, int64(3))
	require.Len(t, page1.Events, 1)

	// Fetch page 2 with limit=1, offset=1.
	var page2 struct {
		Events []struct {
			ID string `json:"id"`
		} `json:"events"`
	}
	doJSON(t, http.MethodGet,
		testServerURL+"/projects/"+tt.ProjectPublicID+"/timeline?limit=1&offset=1",
		tt.AccessToken, nil, &page2)
	require.Len(t, page2.Events, 1)

	// No overlap.
	require.NotEqual(t, page1.Events[0].ID, page2.Events[0].ID,
		"paginated timeline pages must not overlap")
}

// TestProjectAndWorkspaceTimelineHidePrivateTaskEvents verifies that timeline
// endpoints apply Layer-4 private task visibility, not just project membership.
// A project viewer can see non-private project events but must not receive
// payloads or task ids for a private task created by someone else.
func TestProjectAndWorkspaceTimelineHidePrivateTaskEvents(t *testing.T) {
	bootstrap(t)
	t.Parallel()

	owner := newTenant(t)
	viewer := seedProjectRoleMember(t, owner, "viewer")

	var publicTask, privateTask struct {
		ID string `json:"id"`
	}
	doJSON(t, http.MethodPost, testServerURL+"/tasks", owner.AccessToken,
		map[string]any{
			"projectId":  owner.ProjectPublicID,
			"title":      "Timeline public visible",
			"visibility": "public",
		}, &publicTask)
	doJSON(t, http.MethodPost, testServerURL+"/tasks", owner.AccessToken,
		map[string]any{
			"projectId":  owner.ProjectPublicID,
			"title":      "Timeline private hidden",
			"visibility": "private",
		}, &privateTask)
	require.NotEmpty(t, publicTask.ID)
	require.NotEmpty(t, privateTask.ID)

	assertTimelineVisibility := func(t *testing.T, url string) {
		t.Helper()
		var timeline struct {
			Events []struct {
				TaskID string `json:"taskId"`
			} `json:"events"`
		}
		doJSON(t, http.MethodGet, url, viewer.AccessToken, nil, &timeline)
		seen := map[string]bool{}
		for _, ev := range timeline.Events {
			if ev.TaskID != "" {
				seen[ev.TaskID] = true
			}
		}
		require.True(t, seen[publicTask.ID], "viewer must still see public task events from %s", url)
		require.False(t, seen[privateTask.ID], "viewer must not see private task events from %s", url)
	}

	assertTimelineVisibility(t, testServerURL+"/projects/"+owner.ProjectPublicID+"/timeline")
	assertTimelineVisibility(t, testServerURL+"/workspaces/"+owner.WorkspacePublicID+"/timeline")
}
